use rk3588_boot_support::{BarrierOps,ByteTransfer,DelayUs,MemoryTransfer,Mmio32};use crate::stage12::{PmuMcuError,PMUMCU_IMAGE};use crate::stage14::{PmuMcuWakeError,WakeTagSource};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum PmuMcuResumePath{RestoredImage,WakeTags{bytes:u32}}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum PmuMcuResumeError{RestoreStart(PmuMcuError),Wake(PmuMcuWakeError)}
pub fn resume_pmumcu<I:Mmio32+DelayUs+BarrierOps+MemoryTransfer+ByteTransfer>(io:&mut I,restore_enabled:bool,image_saved:bool,tags:WakeTagSource)->Result<PmuMcuResumePath,PmuMcuResumeError>{if crate::stage14::restore_and_start_pmumcu(io,restore_enabled,image_saved,PMUMCU_IMAGE.entry).map_err(PmuMcuResumeError::RestoreStart)?{return Ok(PmuMcuResumePath::RestoredImage)}let bytes=crate::stage14::prepare_pmumcu_wakeup(io,tags,PMUMCU_IMAGE.entry).map_err(PmuMcuResumeError::Wake)?;Ok(PmuMcuResumePath::WakeTags{bytes})}
#[cfg(test)]mod tests{use super::*;struct M{status:u32,words:u32,bytes:u32}impl Mmio32 for M{fn read32(&mut self,a:u64)->u32{match a{0xFD7F0A00=>0x2000,0xFD8D4010=>self.status,_=>0}}fn write32(&mut self,_:u64,_:u32){}}impl DelayUs for M{fn delay_us(&mut self,_:u32){}}impl BarrierOps for M{fn dsb(&mut self){}fn isb(&mut self){}}impl MemoryTransfer for M{fn copy_words_exact(&mut self,_:u64,_:u64,w:u32){self.words=w}}impl ByteTransfer for M{fn copy_bytes_exact(&mut self,_:u64,_:u64,b:u32){self.bytes=b}}#[test]fn fallback(){let mut m=M{status:0,words:0,bytes:0};let r=resume_pmumcu(&mut m,false,false,WakeTagSource::Default{src:0x2000}).unwrap();assert_eq!(r,PmuMcuResumePath::WakeTags{bytes:104});assert_eq!(m.bytes,104);}}
